#[ConfigEntityType(
  id: 'shortcut_set',
  label: new TranslatableMarkup('Shortcut set'),
  label_collection: new TranslatableMarkup('Shortcut sets'),
  label_singular: new TranslatableMarkup('shortcut set'),
