    #[AutowireServiceClosure('logger.responsive_image')]
    protected \Closure $loggerClosure,
    protected ResponsiveImageBuilder $responsiveImageBuilder,
  ) {

  }

  /**
   * Implements hook_theme().
   */
  #[Hook('theme')]
  public function theme() : array {
