        ['data' => $this->t('Step')],
        ['data' => $this->t('Published')],
        ['data' => $this->t('Time')],
        ['data' => $this->t('User')],
        ['data' => $this->t('Message')],
      ],
      '#rows' => $rows,
    ];

    return [
      $table,
      $save ? $this->printSaveAlert(\array_merge($load['past'], [$present], $load['future']), $save) : [],
    ];
  }

