use Drupal\commerce_referral\ReferralManager;
use Drupal\Core\Controller\ControllerBase;
use Symfony\Component\DependencyInjection\ContainerInterface;
use Symfony\Component\HttpFoundation\RedirectResponse;

/**
 * Controller for the referral page.
 */
class ReferralController extends ControllerBase {

  /**
   * The referral manager.
   *
   * @var \Drupal\commerce_referral\ReferralManager
   */
  protected ReferralManager $referralManager;

  /**
   * {@inheritdoc}
   */
  public static function create(ContainerInterface $container): ReferralController {
    $instance = parent::create($container);
    $instance->referralManager = $container->get('commerce_referral.referral_manager');
    return $instance;
  }

  /**
   * Renders the referral page for the current user.
   *
   * @return \Symfony\Component\HttpFoundation\RedirectResponse|mixed[]
   *   The render array if the user is anonymous, or a redirect response if the
   *   user is logged in.
   *
   * @throws \Drupal\Component\Plugin\Exception\InvalidPluginDefinitionException
   * @throws \Drupal\Component\Plugin\Exception\PluginNotFoundException
   * @throws \Drupal\Core\Entity\EntityStorageException
   */
  public function myReferral(): RedirectResponse|array {
    $account = $this->currentUser();
    if ($account->isAnonymous()) {
      return $this->redirect('user.login');
    }
    /** @var ?\Drupal\user\UserInterface $user */
    $user = $this->entityTypeManager()->getStorage('user')->load($account->id());

    if (!$user) {
      return [
        '#markup' => $this->t('Referral is not available at this time.'),
      ];
    }

    $referral = $this->referralManager->ensureReferral($user);
    if (!$referral) {
      return [
        '#markup' => $this->t('Referral is not available at this time.'),
      ];
    }

    // Load the referral coupon code.
    /** @var ?\Drupal\commerce_promotion\Entity\CouponInterface $coupon */
    $coupon = $this->entityTypeManager()->getStorage('commerce_promotion_coupon')->load($referral->get('referral_coupon')->target_id);
    $referral_code = $coupon ? $coupon->getCode() : '';

    // If a kickback coupon has been awarded, load its code.
    $kickback_code = NULL;
    if (!$referral->get('kickback_coupon')->isEmpty()) {
      /** @var ?\Drupal\commerce_promotion\Entity\CouponInterface $kickback_coupon */
      $kickback_coupon = $this->entityTypeManager()->getStorage('commerce_promotion_coupon')->load($referral->get('kickback_coupon')->target_id);
      $kickback_code = $kickback_coupon?->getCode();
    }

    return [
      '#theme' => 'commerce_referral_my_referral',
      '#referral_code' => $referral_code,
      '#kickback_code' => $kickback_code,
      '#attached' => [
        'library' => [],
      ],
    ];
  }

}

