 */
class ReferralListBuilder extends EntityListBuilder {

  /**
   * The entity type manager.
   *
   * @var \Drupal\Core\Entity\EntityTypeManagerInterface
   */
  protected EntityTypeManagerInterface $entityTypeManager;

  /**
   * {@inheritdoc}
   */
  public static function createInstance(ContainerInterface $container, EntityTypeInterface $entity_type): self {
    $instance = parent::createInstance($container, $entity_type);
    $instance->entityTypeManager = $container->get('entity_type.manager');
    return $instance;
  }

  /**
   * {@inheritdoc}
   *
   * @return mixed[]
   *   The header.
   */
  public function buildHeader(): array {
    $header['label'] = $this->t('Label');
    $header['type'] = $this->t('Type');
    $header['referrer_user'] = $this->t('Referrer user');
    $header['referee_user'] = $this->t('Referee user');
    $header['coupons'] = $this->t('Coupons');
    return $header + parent::buildHeader();
  }

  /**
   * {@inheritdoc}
   *
   * @param \Drupal\Core\Entity\EntityInterface $entity
   *   The entity.
   *
   * @return mixed[]
   *   The row.
   *
   * @throws \Drupal\Component\Plugin\Exception\InvalidPluginDefinitionException
   * @throws \Drupal\Component\Plugin\Exception\PluginNotFoundException
   * @throws \Drupal\Core\Entity\EntityMalformedException
   */
  public function buildRow(EntityInterface $entity): array {
    /** @var \Drupal\commerce_referral\Entity\Referral $entity */
    // Label.
    $row['label'] = $this->t('Referral #@id', ['@id' => $entity->id()]);

    // Type (bundle) label.
    $bundle = $this->entityTypeManager->getStorage('commerce_referral_type')->load($entity->get('type')->target_id);
    $row['type'] = $bundle ? $bundle->label() : '';

    // Referrer and referee.
    $referrer = $entity->get('referrer_user')->entity;
    $row['referrer_user'] = Link::fromTextAndUrl($referrer->label() ?? "", $referrer->toUrl());

    $referee = $entity->get('referee_user')->entity;
    $row['referee_user'] = Link::fromTextAndUrl($referee->label() ?? "", $referee->toUrl());

    // Coupons: Show codes and link to edit forms when possible.
    $coupons = [];
    if (!$entity->get('referral_coupon')->isEmpty()) {
      /** @var ?\Drupal\commerce_promotion\Entity\CouponInterface $coupon */
      $coupon = $this->entityTypeManager->getStorage('commerce_promotion_coupon')->load($entity->get('referral_coupon')->target_id);
      if ($coupon) {
        $coupons[] = Link::fromTextAndUrl($this->t('Referral: @code', ['@code' => $coupon->getCode()]), $coupon->toUrl('edit-form'))->toString();
      }
    }
    if (!$entity->get('kickback_coupon')->isEmpty()) {
      /** @var ?\Drupal\commerce_promotion\Entity\CouponInterface $coupon */
      $coupon = $this->entityTypeManager->getStorage('commerce_promotion_coupon')->load($entity->get('kickback_coupon')->target_id);
      if ($coupon) {
        $coupons[] = Link::fromTextAndUrl($this->t('Kickback: @code', ['@code' => $coupon->getCode()]), $coupon->toUrl('edit-form'))->toString();
      }
    }
    $row['coupons'] = [
      'data' => [
        '#type' => 'inline_template',
        '#template' => '{{ items|safe_join(", ") }}',
        '#context' => ['items' => $coupons],
      ],
    ];

    // Operations last.
    $row['operations'] = [
      'data' => [
        '#type' => 'operations',
        '#links' => $this->getOperations($entity),
      ],
    ];

    return $row;
  }

}

